import{_ as i,D as n,o as r,c,m as e,a as t,G as a,S as d}from"./chunks/framework.DuIEtbrD.js";const F=JSON.parse('{"title":"DeepSeek宝藏组合！牛马们福音来了","description":"无论你是职场新人还是忙碌的打工族，这款高效设计工具组合都将是你工作中的得力助手！","frontmatter":{"title":"DeepSeek宝藏组合！牛马们福音来了","description":"无论你是职场新人还是忙碌的打工族，这款高效设计工具组合都将是你工作中的得力助手！","keywords":"deepseek,kimi,canva,xmind,obsidian,飞书,cursor,短视频,脚本,小红书,爆款文案,命理大师,图表,PPT,表格","logo":"https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/deepseek.png"},"headers":[],"relativePath":"article/2025/deepseek-tool-chain.md","filePath":"article/2025/deepseek-tool-chain.md","lastUpdated":1776945570000}'),b={name:"article/2025/deepseek-tool-chain.md"};function m(h,s,u,y,g,D){const p=n("Obsolete"),l=n("Reward"),o=n("Gitalk");return r(),c("div",null,[s[0]||(s[0]=e("h1",{id:"deepseek宝藏组合-牛马们福音来了",tabindex:"-1"},[t("DeepSeek宝藏组合！牛马们福音来了 "),e("a",{class:"header-anchor",href:"#deepseek宝藏组合-牛马们福音来了","aria-label":'Permalink to "DeepSeek宝藏组合！牛马们福音来了"'},"​")],-1)),a(p,{date:"2025-02-20"}),s[1]||(s[1]=d(`<p>在当今快节奏的职场中，无论是朝九晚五的上班族，还是自由职业者，每天都面临着巨大的工作压力和繁重的任务量。写文案、做策划、数据分析……这些看似永无止境的工作，常常让人感到力不从心。</p><p>你是否也曾为完成一份高质量的报告而熬夜加班？是否曾为抓到客户方案的灵感而苦苦思索？又是否曾因为效率低下而错过了晋升的机会？</p><p>现在，有一种宝藏组合正在改变这一切——DeepSeek！</p><p>在这篇文章中，我们将使用DeepSeek与其他工具的“宝藏组合”来实现背后的无限可能！</p><h2 id="deepseek-kimi-ppt神器" tabindex="-1">DeepSeek+Kimi PPT神器 <a class="header-anchor" href="#deepseek-kimi-ppt神器" aria-label="Permalink to &quot;DeepSeek+Kimi PPT神器&quot;">​</a></h2><p>打开<a href="https://chat.deepseek.com/" target="_blank" rel="noreferrer">DeepSeek</a>输入：</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#FFCB6B;">我是游戏职业选手，请为我生成</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">王者荣耀和英雄联盟</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;"> 对比 PPT内容</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>生成以下PPT内容：</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#676E95;font-style:italic;">### **《王者荣耀 vs 英雄联盟》对比 PPT 内容**</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FFCB6B;">---</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#### **封面页**</span></span>
<span class="line"><span style="color:#FFCB6B;">-</span><span style="color:#C3E88D;"> 标题：</span><span style="color:#BABED8;">**</span><span style="color:#C3E88D;">《王者荣耀 vs 英雄联盟》游戏对比分析</span><span style="color:#BABED8;">**</span></span>
<span class="line"><span style="color:#FFCB6B;">-</span><span style="color:#C3E88D;"> 副标题：</span><span style="color:#BABED8;">**</span><span style="color:#C3E88D;">职业选手视角下的差异与策略</span><span style="color:#BABED8;">**</span></span>
<span class="line"><span style="color:#FFCB6B;">-</span><span style="color:#C3E88D;"> 图片：王者荣耀和英雄联盟的Logo拼图</span></span>
<span class="line"><span style="color:#FFCB6B;">-</span><span style="color:#C3E88D;"> 作者/时间：（可选）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FFCB6B;">---</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">### **目录**</span></span>
<span class="line"><span style="color:#FFCB6B;">1.</span><span style="color:#C3E88D;"> 游戏背景与玩法对比  </span></span>
<span class="line"><span style="color:#FFCB6B;">2.</span><span style="color:#C3E88D;"> 操作方式与技能机制  </span></span>
<span class="line"><span style="color:#FFCB6B;">3.</span><span style="color:#C3E88D;"> 地图设计与游戏节奏  </span></span>
<span class="line"><span style="color:#FFCB6B;">4.</span><span style="color:#C3E88D;"> 游戏经济与资源控制  </span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">## 省略...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><p>然后复制这段内容脚本，打开<a href="https://kimi.moonshot.cn/" target="_blank" rel="noreferrer">Kimi</a>喂给它，让他生成PPT文件：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-02-19_15.49.46.png" alt=""></p><p>点击开始就会开始处理：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/2025-02-19%2015.46.27.gif" alt=""></p><p>生成后直接下载生成的文件即可</p><p>除此之外，还可以选择模版、在线编辑</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-02-19_15.45.50.png" alt=""></p><h2 id="deepseek-canva-海报神器" tabindex="-1">DeepSeek+Canva 海报神器 <a class="header-anchor" href="#deepseek-canva-海报神器" aria-label="Permalink to &quot;DeepSeek+Canva 海报神器&quot;">​</a></h2><p>打开<a href="https://chat.deepseek.com/" target="_blank" rel="noreferrer">DeepSeek</a>输入：</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#FFCB6B;">请制定一份青少年周末规划，以列表的形式展示在海报上，并给出海报的背景说明</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>生成以下海报脚本内容：</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#FFCB6B;">青少年周末规划海报</span></span>
<span class="line"><span style="color:#FFCB6B;">海报标题</span></span>
<span class="line"><span style="color:#FFCB6B;">“青春不设限，周末乐无限！”</span></span>
<span class="line"><span style="color:#FFCB6B;">——活力周末，成长与欢乐同行</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FFCB6B;">周末活动规划表</span></span>
<span class="line"><span style="color:#FFCB6B;">时间轴</span><span style="color:#C3E88D;"> + 主题活动</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 省略...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>打开<a href="https://www.canva.com/" target="_blank" rel="noreferrer">Canva</a>将生成的脚本内容输入进入，开始生成：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-02-19_14.51.58.png" alt=""></p><p>很快就会生成符合预期的海报：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-02-19_14.53.37.png" alt=""></p><p>Canva也支持在线编辑生成后海报，满足用户的自定义需求</p><h2 id="deepseek-xmind-脑图神器" tabindex="-1">DeepSeek+Xmind 脑图神器 <a class="header-anchor" href="#deepseek-xmind-脑图神器" aria-label="Permalink to &quot;DeepSeek+Xmind 脑图神器&quot;">​</a></h2><p>打开<a href="https://chat.deepseek.com/" target="_blank" rel="noreferrer">DeepSeek</a>输入：</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#FFCB6B;">请为我制定</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">Java学习路线</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">，并以markdown的格式输出</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>生成以下markdown内容：</p><div class="language-md line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#89DDFF;"># </span><span style="color:#FFCB6B;">Java 学习路线</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;">## </span><span style="color:#FFCB6B;">1. 入门基础</span></span>
<span class="line"><span style="color:#89DDFF;">### </span><span style="color:#FFCB6B;">1.1 什么是Java？</span></span>
<span class="line"><span style="color:#89DDFF;">-</span><span style="color:#89DDFF;font-weight:bold;"> **</span><span style="color:#F07178;font-weight:bold;">简介</span><span style="color:#89DDFF;font-weight:bold;">**</span><span style="color:#BABED8;">：Java 是一种面向对象的编程语言，广泛应用于企业级应用、Android开发等领域。</span></span>
<span class="line"><span style="color:#89DDFF;">-</span><span style="color:#89DDFF;font-weight:bold;"> **</span><span style="color:#F07178;font-weight:bold;">特点</span><span style="color:#89DDFF;font-weight:bold;">**</span><span style="color:#BABED8;">：</span></span>
<span class="line"><span style="color:#89DDFF;">  -</span><span style="color:#BABED8;"> 跨平台（一次编译，到处运行）。</span></span>
<span class="line"><span style="color:#89DDFF;">  -</span><span style="color:#BABED8;"> 面向对象。</span></span>
<span class="line"><span style="color:#89DDFF;">  -</span><span style="color:#BABED8;"> 多线程支持。</span></span>
<span class="line"><span style="color:#89DDFF;"># </span><span style="color:#FFCB6B;">省略 ...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>将以上内容保存为markdown文件，然后打开xmind导入刚刚生成的文件：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-02-19_18.33.28.png" alt=""></p><p>一份完整的思维脑图就成功了！</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-02-19_18.34.23.png" alt=""></p><h2 id="deepseek-obsidian-知识库神器" tabindex="-1">DeepSeek+Obsidian 知识库神器 <a class="header-anchor" href="#deepseek-obsidian-知识库神器" aria-label="Permalink to &quot;DeepSeek+Obsidian 知识库神器&quot;">​</a></h2><p>平时用<a href="https://obsidian.md" target="_blank" rel="noreferrer">Obsidian</a>来写笔记，现在也可以通过AI插件来快速写作，并形成自己的知识库</p><p>配置步骤非常简单，只需要Copliot、Ollama本地运行DeepSeek即可，如果你不懂本地部署DeepSeek，可以阅读往期文章 <a href="/article/2025/deepseek-local.html">本地部署DeepSeek摆脱服务器繁忙</a></p><p>首先安装插件Copilot：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-02-19_18.43.35%202.png" alt=""></p><p>安装完后点击配置Model，点击<code>Add Custom Model</code>添加自定义模型：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-02-19_18.50.09%202.png" alt=""></p><p>这里选择Ollama并配置自己本地已有的模型</p><p>现在就可以使用了！</p><p>打开一篇文章，点击Copilot选择对应的模型后，输入<code>总结[[文章标题]]</code>回车后就可以总结了</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-02-19_19.00.20%202.png" alt=""></p><p>此插件还支持文章纠正、写作等很多功能，对于平时记笔记的小伙伴来说非常有帮助</p><h2 id="deepseek-notion-知识库神器" tabindex="-1">DeepSeek+Notion 知识库神器 <a class="header-anchor" href="#deepseek-notion-知识库神器" aria-label="Permalink to &quot;DeepSeek+Notion 知识库神器&quot;">​</a></h2><p>请参考Obsidian</p><h2 id="deepseek-飞书-批处理神器" tabindex="-1">DeepSeek+飞书 批处理神器 <a class="header-anchor" href="#deepseek-飞书-批处理神器" aria-label="Permalink to &quot;DeepSeek+飞书 批处理神器&quot;">​</a></h2><p><a href="https://www.feishu.cn" target="_blank" rel="noreferrer">飞书</a> 多维表格现已支持AI功能，并且支持多种大模型。可以批量生图、文案、图表分析等等功能</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-02-19_19.40.38.png" alt=""></p><p>首先打开飞书新建一个多维表格，新增第一列<code>主题</code></p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-02-19_19.44.43.png" alt=""></p><p>再添加第二列填写模型标题，然后选择<code>Deepseek R1</code>探索字段捷径</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-02-19_19.45.22.png" alt=""></p><p>接着翻到下面配置主题，勾选思考过程、思考结果</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-02-19_19.45.46.png" alt=""></p><p>现在只要在第一列输入文章的主题，就会自动生成文章内容了</p><h2 id="deepseek-剪映-短视频神器" tabindex="-1">DeepSeek+剪映 短视频神器 <a class="header-anchor" href="#deepseek-剪映-短视频神器" aria-label="Permalink to &quot;DeepSeek+剪映 短视频神器&quot;">​</a></h2><p>打开DeepSeek输入：</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#FFCB6B;">请为生成以</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">单板滑雪技巧</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;"> 为主题的短视频脚本</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>生成以下短视频脚本：</p><div class="language-md line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#BABED8;">【视频标题】</span></span>
<span class="line"><span style="color:#BABED8;">单板滑雪技巧 | 掌握基础动作，享受飞驰快感！</span></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">【片头】 (0:00-0:05)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">画面：俯瞰雪山全景、阳光洒在雪地上，镜头缓慢推进。</span></span>
<span class="line"><span style="color:#BABED8;">字幕：单板滑雪技巧</span></span>
<span class="line"><span style="color:#BABED8;">旁白/音乐：动感背景音乐渐入，旁白：“准备好迎接冬日的挑战了吗？”</span></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">【第一部分：装备与热身】 (0:06-0:20)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">画面：运动员检查滑雪装备（单板、滑雪鞋、护具等），快速切换热身动作镜头。</span></span>
<span class="line"><span style="color:#BABED8;">字幕：1. 检查装备 2. 热身运动</span></span>
<span class="line"><span style="color:#BABED8;">旁白：“开始前，确保装备完好并进行充分热身。安全第一，享受运动！”</span></span>
<span class="line"><span style="color:#89DDFF;"># </span><span style="color:#FFCB6B;">省略...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>打开剪映的文本生成视频，将脚本录入后一键生成：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-02-19_20.01.24.png" alt=""></p><h2 id="deepseek-cursor-编程神器" tabindex="-1">DeepSeek+Cursor 编程神器 <a class="header-anchor" href="#deepseek-cursor-编程神器" aria-label="Permalink to &quot;DeepSeek+Cursor 编程神器&quot;">​</a></h2><p>下载<a href="https://www.cursor.com/cn" target="_blank" rel="noreferrer">Cursor</a>后配置DeepSeek模型，输入项目主题生成，这里先不多做介绍</p><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><p>除此之外还可以使用DeepSeek进行股市分析、图表分析等等，敬请关注后续分享</p>`,70)),a(l),a(o)])}const B=i(b,[["render",m]]);export{F as __pageData,B as default};
